func TestErrorMessages(t *testing.T) {
	sizes := map[string]PackSizes{"BOLT-M6": {PiecesPerBox: 50, BoxesPerPallet: 40}}

	// Test non-whole result error message
	t.Run("non-whole error for 7 pcs to boxes", func(t *testing.T) {
		_, err := Convert("BOLT-M6", sizes, 7, "pcs", "boxes")
		if err == nil {
			t.Fatal("expected an error")
		}
