package main

import (
	"fmt"
	"os"
)

func main() {
	if len(os.Args) < 2 {
		fmt.Fprintln(os.Stderr, "usage: tarnbrook <import|convert> ...")
		os.Exit(2)
	}

	switch os.Args[1] {
	case "convert":
		handleConvert()
	default:
		fmt.Fprintf(os.Stderr, "tarnbrook: %s: not wired in this build\n", os.Args[1])
		os.Exit(2)
	}
}

func handleConvert() {
	if len(os.Args) != 6 {
		fmt.Fprintln(os.Stderr, "usage: tarnbrook convert <sku> <qty> <from> <to>")
		os.Exit(2)
	}

	sku := os.Args[2]
	qtyStr := os.Args[3]
	from := os.Args[4]
	to := os.Args[5]

	qty := 0
	_, err := fmt.Sscanf(qtyStr, "%d", &qty)
	if err != nil {
		fmt.Fprintf(os.Stderr, "tarnbrook: convert: invalid quantity %q\n", qtyStr)
		os.Exit(2)
	}

	// Load pack sizes (hardcoded for now with test data)
	sizes := map[string]PackSizes{
		"BOLT-M6": {PiecesPerBox: 50, BoxesPerPallet: 40},
		"WASHER":  {PiecesPerBox: 100, BoxesPerPallet: 20},
	}

	result, err := Convert(sku, sizes, qty, from, to)
	if err != nil {
		fmt.Fprintf(os.Stderr, "tarnbrook: convert: %v\n", err)
		os.Exit(1)
	}

	fmt.Println(result)
}

