package main

import (
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"testing"
)

func buildBinary(t *testing.T) string {
	dir := t.TempDir()
	binPath := filepath.Join(dir, "tarnbrook")

	cmd := exec.Command("go", "build", "-o", binPath, "./...")
	cmd.Dir = "../"
	if output, err := cmd.CombinedOutput(); err != nil {
		t.Fatalf("build failed: %v\n%s", err, output)
	}
	return binPath
}

func runConvert(t *testing.T, bin string, args ...string) (string, string, int) {
	cmd := exec.Command(bin, append([]string{"convert"}, args...)...)

	stdout, _ := cmd.CombinedOutput()
	exitCode := cmd.ProcessState.ExitCode()

	return string(stdout), "", exitCode
}

func TestCLI(t *testing.T) {
	// Build binary
	bin := buildBinary(t)

	t.Run("successful conversion pcs to boxes", func(t *testing.T) {
		t.Parallel()
		stdout, stderr, code := runConvert(t, bin, "BOLT-M6", "150", "pcs", "boxes")
		t.Logf("=== Successful conversion ===")
		t.Logf("Command: %s convert BOLT-M6 150 pcs boxes", bin)
		t.Logf("Exit code: %d", code)
		t.Logf("Output: %s", stdout)
		if stderr != "" {
			t.Logf("Stderr: %s", stderr)
		}
	})

	t.Run("sku with no pack size", func(t *testing.T) {
		t.Parallel()
		stdout, stderr, code := runConvert(t, bin, "UNKNOWN-SKU", "1", "boxes", "pcs")
		t.Logf("=== SKU with no pack size ===")
		t.Logf("Command: %s convert UNKNOWN-SKU 1 boxes pcs", bin)
		t.Logf("Exit code: %d", code)
		t.Logf("Output: %s", stdout)
		if stderr != "" {
			t.Logf("Stderr: %s", stderr)
		}
	})

	t.Run("non-whole result", func(t *testing.T) {
		t.Parallel()
		stdout, stderr, code := runConvert(t, bin, "BOLT-M6", "7", "pcs", "boxes")
		t.Logf("=== Non-whole result ===")
		t.Logf("Command: %s convert BOLT-M6 7 pcs boxes", bin)
		t.Logf("Exit code: %d", code)
		t.Logf("Output: %s", stdout)
		if stderr != "" {
			t.Logf("Stderr: %s", stderr)
		}
	})
}

