28	func ReadStock(r io.Reader) ([]Row, []RowError, error) {
29		reader := csv.NewReader(r)
30		reader.FieldsPerRecord = -1
31	
32		var rows []Row
33		var bad []RowError
34	
35		for line := 1; ; line++ {
36			record, err := reader.Read()
37			if errors.Is(err, io.EOF) {
38				return rows, bad, nil
39			}
