46			}
47			qty, err := strconv.Atoi(strings.TrimSpace(record[1]))
48			if err != nil {
49				bad = append(bad, RowError{Line: line, Err: fmt.Errorf("quantity %q: %w", record[1], err)})
50				continue
51			}
52			rows = append(rows, Row{Name: strings.TrimSpace(record[0]), Quantity: qty, Unit: strings.TrimSpace(record[2])})
